const fs=require('fs'),vm=require('vm'),assert=require('assert/strict');
const labels=Array.from({length:20},(_,i)=>'NCT'+i),values=labels.map((_,i)=>i);
const identities=labels.map((id,i)=>({registry_id:id,axis_label:i<18?'Short drug '+i:'Long complete intervention '+('component '.repeat(20))+i,label:'Source '+i}));
const rows=labels.map((id,i)=>({dataset:{trial:id},style:{},textContent:i<18?'short':'long'}));
const elements={charts:{textContent:JSON.stringify({size:{labels,values,identities}})},'tbl-c':{id:'tbl-c',querySelectorAll:()=>rows}};
elements['chart-size']={id:'chart-size',style:{},closest:()=>({hidden:false})};
let input;const filter={value:'',getAttribute:()=>'tbl-c',addEventListener:(_,fn)=>input=fn};
const handlers={},options=[];let registrations=0;
const instance={setOption:o=>options.push(o),resize(){},dispose(){},on(name,fn){handlers[name]=fn;registrations++;}};
const document={getElementById:id=>elements[id],querySelectorAll:s=>s==='input[data-filter]'?[filter]:[]};
const echarts={graphic:{Text:class{constructor(o){this.text=o.style.text;}getBoundingRect(){return{height:this.text.length>80?110:22};}}},init:()=>instance};
vm.runInNewContext(fs.readFileSync(process.argv[2],'utf8'),{document,window:{echarts,addEventListener(){}},echarts,ResizeObserver:class{observe(){}},Map,Set});
let o=options.at(-1);assert.equal(o.dataZoom[0].endValue,5,'offscreen long labels must not collapse the first six short labels');
assert.equal(o.series[0].data.length,20);assert.equal(o.series[0].data[0],0);
assert.equal(typeof handlers.datazoom,'function');handlers.datazoom({startValue:18});o=options.at(-1);
assert.equal(o.dataZoom[0].startValue,18);assert.equal(o.dataZoom[0].endValue,19);
assert.ok((parseInt(elements['chart-size'].style.height)-54)/2>=118,'visible long labels retain measured space');
handlers.datazoom({startValue:18,endValue:18});o=options.at(-1);assert.equal(o.dataZoom[0].endValue,18,'a user-selected single-study window stays selected');
filter.value='long';input();o=options.at(-1);assert.equal(o.series[0].data.length,2);assert.equal(o.dataZoom[0].startValue,0);
filter.value='';input();o=options.at(-1);assert.equal(o.series[0].data.length,20);assert.equal(o.dataZoom[0].endValue,5);assert.equal(registrations,1);
